fn nums(s:&str)->Vec<u64>{s.split(|c:char|!c.is_ascii_digit()).filter(|s|!s.is_empty()).map(|s|s.parse().unwrap()).collect()}
fn pparse(s:&str)->P{let a=nums(s);assert_eq!(a.len()%9,0);a.chunks(9).map(|v|{let mut r=Z;r.copy_from_slice(v);r}).collect()}
fn dparse(s:&str)->D{let(u,v)=s.split(" u=").nth(1).unwrap().split_once(" v=").unwrap();D{u:pparse(u),v:pparse(v)}}
fn pe(x:&[u8;8],y:&[u8;8],e:&[[u8;8];8])->u8{let mut s=0u64;for i in 0..8{for j in 0..8{s+=x[i]as u64*e[i][j]as u64*y[j]as u64}}(s%4)as u8}
fn point(c:&C,h:&[D],x:&[u8;8])->D{let mut p=c.zero();for i in 0..8{p=c.add(&p,&c.mul(&h[i],x[i]as usize))}p}
fn log4(f:&F,z:E,a:E)->u8{(0u8..4).find(|&k|f.pow(z,k as u64)==a).expect("notfourthroot")}
fn binary(mut rows:Vec<u64>)->u32{let mut r=0;let mut piv=vec![];for j in 0..32{let Some(i)=(r..rows.len()).find(|&i|rows[i]&(1<<j)!=0)else{continue};rows.swap(i,r);for i in 0..rows.len(){if i!=r&&rows[i]&(1<<j)!=0{rows[i]^=rows[r]}}piv.push(j);r+=1;}for &a in &rows{assert!(a&0xffffffff!=0||a&(1<<32)==0)}let mut out=0;for(i,&j)in piv.iter().enumerate(){if rows[i]&(1<<32)!=0{out|=1<<j}}out}
fn solve4(t:&[[u8;8];4],b:[u8;4])->[u8;8]{let mut a=[[0u8;9];4];for i in 0..4{a[i][..8].copy_from_slice(&t[i]);a[i][8]=b[i]}let mut r=0;let mut piv=vec![];for j in 0..8{if r==4{break}let Some(i)=(r..4).find(|&i|a[i][j]%2==1)else{continue};a.swap(i,r);let inv=a[r][j];for k in 0..9{a[r][k]=(a[r][k]*inv)%4}for i in 0..4{if i==r{continue}let z=a[i][j];for k in 0..9{a[i][k]=(a[i][k]+16-z*a[r][k])%4}}piv.push(j);r+=1}assert_eq!(r,4);let mut x=[0;8];for(i,&j)in piv.iter().enumerate(){x[j]=a[i][8]}for i in 0..4{assert_eq!((0..8).map(|j|t[i][j]as u64*x[j]as u64).sum::<u64>()%4,b[i]as u64)}x}
