 let old=a;let mut rows=vec![];for i in 0..4{for j in i+1..4{let w=pe(&a[i],&a[j],&e);assert_eq!(w%2,0);let mut row=((w/2)as u64)<<32;for k in 0..8{let mut unit=[0;8];unit[k]=1;if pe(&unit,&a[j],&e)%2!=0{row|=1u64<<(i*8+k)}if pe(&a[i],&unit,&e)%2!=0{row|=1u64<<(j*8+k)}}rows.push(row)}}let adjustment=binary(rows.clone());for row in rows{assert_eq!(((row as u32&adjustment).count_ones()%2)as u64,(row>>32)&1)}for i in 0..4{for k in 0..8{a[i][k]=(a[i][k]+2*((adjustment>>(8*i+k))&1)as u8)%4}}for i in 0..4{for j in 0..4{assert_eq!(pe(&a[i],&a[j],&e),0)}for k in 0..8{assert_eq!(a[i][k]%2,old[i][k])}}
 let mut t=[[0u8;8];4];for i in 0..4{for j in 0..8{let mut unit=[0;8];unit[j]=1;t[i][j]=pe(&a[i],&unit,&e)}}let mut b=[[0;8];4];for i in 0..4{let mut rhs=[0;4];rhs[i]=1;b[i]=solve4(&t,rhs)}let mut mm=[[0u8;4];4];for i in 0..4{for j in 0..4{mm[i][j]=pe(&b[i],&b[j],&e)}}let oldb=b;for j in 0..4{for i in 0..j{for k in 0..8{b[j][k]=(b[j][k]+mm[i][j]*a[i][k])%4}}}for i in 0..4{for j in 0..4{assert_eq!(pe(&b[i],&b[j],&e),0);assert_eq!(pe(&a[i],&b[j],&e),(i==j)as u8)}}
 let mut basis=a.to_vec();basis.extend(b);let actual=basis.iter().map(|x|point(&c,&h,x)).collect::<Vec<_>>();for(i,p)in actual.iter().enumerate(){assert!(c.valid(p));assert_eq!(p.u.len(),5);assert_eq!(c.mul(p,4),c.zero());assert_ne!(c.add(p,p),c.zero());let expected=basis[i].iter().enumerate().filter(|(_,v)|**v%2==1).fold(c.zero(),|s,(j,_)|c.add(&s,&c.branch(roots[j])));assert_eq!(c.add(p,p),expected);println!("SYMPLECTIC index={i} coefficients={:?} u={:?} v={:?}",basis[i],p.u,p.v)}
