 let mut distinct=std::collections::BTreeSet::new();let mut doubled=std::collections::BTreeSet::new();for coeff in 0..256usize{let mut x=[0u8;8];for i in 0..4{let z=((coeff>>(2*i))&3)as u8;for k in 0..8{x[k]=(x[k]+z*a[i][k])%4}}let p=point(&c,&h,&x);assert!(distinct.insert(p.clone()));doubled.insert(c.add(&p,&p));}assert_eq!(distinct.len(),256);assert_eq!(doubled.len(),16);
